contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(actor != address(c));
        vm.assume(actor != address(this));
        amount = bound(amount, 1, 1e30);
        vm.deal(actor, amount);
        vm.prank(actor);
        c.deposit{value: amount}();
        vm.prank(actor);
        bool ok;
        try c.withdrawAll() { ok = true; } catch { ok = false; }
        // General rule: after a successful full withdrawal of the only outstanding credit,
        // no Ether may remain held by C; the tracked ledger and the real holdings agree.
        assertTrue(ok ? address(c).balance == 0 : address(c).balance == amount);
    }
}
